{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Offerings & Investment — {{BUSINESS_NAME}}</title>
  <style>
    :root{--glass:#ffffff33;--glass-2:#ffffff22;--accent:#7b5cff;--accent-2:#ff8da1;--muted:#6b6b6b;--card:#ffffffaa}
    *{box-sizing:border-box;font-family:Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial}
    body{margin:0;min-height:100vh;background:linear-gradient(180deg,#f7f3ff 0%,#fff 100%);-webkit-font-smoothing:antialiased;color:#222}
    .nav{display:flex;justify-content:space-between;align-items:center;padding:18px 28px;backdrop-filter:blur(8px);background:linear-gradient(180deg,rgba(255,255,255,0.6),rgba(255,255,255,0.35));border-bottom:1px solid rgba(255,255,255,0.4)}
    .brand{font-weight:700;color:var(--accent)}
    .menu{display:flex;gap:14px}
    .menu a{color:#333;text-decoration:none;padding:8px;border-radius:10px}
    .menu a:hover{background:#ffffff55}
    header.hero{padding:48px;display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:start}
    .panel{background:var(--glass);border-radius:14px;padding:22px;box-shadow:0 6px 22px rgba(20,15,40,0.06);border:1px solid rgba(255,255,255,0.6)}
    h1{margin:0 0 8px;font-size:28px}
    p.lead{margin:0;color:var(--muted)}

    .pricing-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:18px}
    .card{background:linear-gradient(180deg,rgba(255,255,255,0.7),rgba(255,255,255,0.55));padding:18px;border-radius:12px;border:1px solid rgba(0,0,0,0.04)}
    .card h3{margin:0 0 6px}
    .price{font-size:22px;font-weight:700;color:var(--accent)}
    .features{margin:10px 0;color:var(--muted);font-size:14px}
    .cta{display:inline-block;margin-top:12px;padding:10px 14px;background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#fff;border-radius:10px;text-decoration:none}

    .note{font-size:13px;color:var(--muted);margin-top:12px}
    footer{padding:28px;text-align:center;color:var(--muted)}

    /* mood badge small */
    .mood-inline{display:inline-flex;align-items:center;gap:10px;padding:8px;border-radius:999px;background:rgba(123,92,255,0.08);border:1px solid rgba(123,92,255,0.14)}

    /* Aroma wheel teaser */
    .wheel{display:flex;justify-content:center;margin-top:18px}
    .wheel svg{width:220px;height:220px}
    .tooltip{position:fixed;pointer-events:none;background:#111;color:#fff;padding:8px 10px;border-radius:8px;font-size:13px;transform:translate(-50%,-110%);opacity:0;transition:opacity 0.14s ease}
  </style>
</head>
<body>
  <nav class="nav">
    <div class="brand">{{BUSINESS_NAME}}</div>
    <div class="menu">
      <a href="index.html">Gather</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Blends</a>
      <a href="shop.html">Boutique</a>
      <a href="pricing.html">Investment</a>
      <a href="about.html">About</a>
      <a href="book.html">Sessions</a>
      <a href="contact.html">Reach</a>
    </div>
  </nav>

  <header class="hero">
    <div class="panel">
      <h1>Choiceful offerings for your small daily rituals</h1>
      <p class="lead">Packages and products framed for moments — from a pocket-sized ritual to a guided scent session. Each option may support calm, focus, or restful transitions depending on how you use it.</p>

      <div class="pricing-grid" role="list">
        <div class="card" role="listitem">
          <h3>Pocket Ritual</h3>
          <div class="price">$28</div>
          <div class="features">Roller with a ready-made trio for on-the-go ease. 10 mL; pre-diluted for topical use.</div>
          <a class="cta" href="shop.html">Add to cart</a>
          <div class="note">Includes basic safety guide and dilution notes.</div>
        </div>

        <div class="card" role="listitem">
          <h3>Home Blending Kit</h3>
          <div class="price">$72</div>
          <div class="features">A curated set of 6 single notes plus a base oil for simple at-home blends and small experiments.</div>
          <a class="cta" href="blends.html">View kit</a>
          <div class="note">Perfect for learning the aroma wheel and building your own scent shorthand.</div>
        </div>

        <div class="card" role="listitem">
          <h3>Guided Scent Session</h3>
          <div class="price">$125</div>
          <div class="features">One-on-one 50-minute session to explore sensations, craft a short-term plan, and leave with a personalised take-home blend.</div>
          <a class="cta" id="book-cta" href="book.html">Book a session</a>
          <div class="note">Sessions emphasize safety, scent education, and supportive routines.</div>
        </div>
      </div>

      <p style="margin-top:18px;color:var(--muted);font-size:13px">All products and sessions are retail offerings. Aromatherapy may support comfort and focus for some people; it is not a replacement for medical care.</p>
    </div>

    <aside class="panel">
      <div style="display:flex;justify-content:space-between;align-items:center">
        <div>
          <strong>Quick match</strong>
          <div style="font-size:13px;color:var(--muted)">Pick a mood to see a suggested starting point</div>
        </div>
      </div>

      <div style="margin-top:12px">
        <select id="mood-select" aria-label="Select mood" style="width:100%;padding:10px;border-radius:10px;border:1px solid rgba(0,0,0,0.06)">
          <option value="stressed">I feel frazzled</option>
          <option value="sleepy">I want to wind down</option>
          <option value="focus">I need focus</option>
          <option value="grounded">Want to feel steady</option>
          <option value="uplifted">Ready to play</option>
        </select>
      </div>

      <div id="method-card" style="margin-top:16px;padding:12px;border-radius:10px;background:var(--glass-2);">
        <strong id="method-title">Gentle ritual</strong>
        <div id="method-copy" style="color:var(--muted);font-size:14px;margin-top:6px">Begin with a single roll of a calming blend, inhale twice with intention, and place the roller in your bag for moments of overflow.</div>
        <a id="method-cta" href="book.html" class="cta" style="display:inline-block;margin-top:10px">Reserve a session</a>
      </div>

      <div class="wheel" aria-hidden="true">
        <svg viewBox="0 0 200 200">
          <defs>
            <linearGradient id="g1" x1="0" x2="1"><stop offset="0" stop-color="#7b5cff" stop-opacity="0.9"/><stop offset="1" stop-color="#ff8da1" stop-opacity="0.9"/></linearGradient>
          </defs>
          <circle cx="100" cy="100" r="90" fill="url(#g1)" opacity="0.12"/>
          <!-- simple three-note markers -->
          <g id="notes">
            <circle class="note-dot" data-note="Top" data-desc="Bright, evaporative scents; quick to notice and fade." cx="100" cy="30" r="12" fill="#ffcc6b" stroke="#fff" stroke-width="2"/>
            <circle class="note-dot" data-note="Middle" data-desc="The heart of a blend; floral, herbal, fruity notes that shape the character." cx="170" cy="110" r="12" fill="#a0d3a7" stroke="#fff" stroke-width="2"/>
            <circle class="note-dot" data-note="Base" data-desc="Deeper, long-lasting anchors like woods, resins, and musks." cx="30" cy="110" r="12" fill="#c9b1ff" stroke="#fff" stroke-width="2"/>
          </g>
        </svg>
      </div>

    </aside>
  </header>

  <main style="padding:0 28px 28px">
    <section style="display:flex;gap:18px;margin-top:18px">
      <div class="panel" style="flex:1">
        <h3>How pricing is framed</h3>
        <p style="color:var(--muted)">Options are offered as entryways: something to try, something to make at home, and something to work through with a practitioner. All purchases include clear guidance on safe dilution, how to patch test, and general storage advice.</p>
      </div>

      <div class="panel" style="width:320px">
        <h4>Why retail + sessions?</h4>
        <p style="color:var(--muted)">Most people like a small practice they can own. Sessions pair well with kits so you can leave with a tangible plan and products that fit it.</p>
      </div>
    </section>

    <section style="margin-top:18px">
      <div class="panel">
        <h3>Testimonials</h3>
        <div style="color:var(--muted);margin-top:10px">
          "A short session helped me choose a daily roll I actually use." — S., {{CITY}}
        </div>
      </div>
    </section>

    <section style="margin-top:18px">
      <div class="panel">
        <h3>Safety & notes</h3>
        <ul style="color:var(--muted);margin-top:10px">
          <li>Instructions for dilution are included with all oils; follow them carefully.</li>
          <li>Perform a patch test before regular topical use.</li>
          <li>Keep essential oils away from pets' food and water; some oils are not pet-safe.</li>
          <li>If pregnant or nursing, consult a qualified provider before using essential oils.</li>
        </ul>
      </div>
    </section>
  </main>

  <footer>
    <div style="max-width:900px;margin:0 auto;display:flex;justify-content:space-between;align-items:center;padding:12px 18px">
      <div style="text-align:left">© <strong>{{BUSINESS_NAME}}</strong> • {{CITY}}, {{STATE}} • <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
      <div style="text-align:right;color:var(--muted)">Made with care — retail + practice</div>
    </div>
  </footer>

  <div id="tooltip" class="tooltip" aria-hidden="true"></div>

  <script>
    // Mood-to-Method selector: updates method copy and CTA
    const moodMap = {
      stressed: {title:'Short centering', copy:'A single inhalation practice with a grounding base blend. Carry a roller and use at tense moments.', cta:'Schedule a short consult', href:'book.html?type=center'},
      sleepy: {title:'Slow-down ritual', copy:'A wind-down diffuser recipe plus mindful breathing before bed. Avoid stimulating notes near sleep.', cta:'Get a bedtime plan', href:'book.html?type=sleep'},
      focus: {title:'Focused clarity', copy:'A small inhaler or focused spritz with bright middle notes to cue attention for 30–60 minutes.', cta:'Try a focus kit', href:'shop.html'},
      grounded: {title:'Anchor practice', copy:'Repeatable grounding sequence: three slow breaths, apply a drop to palms, cup, and inhale.', cta:'Explore grounding sessions', href:'book.html?type=ground'},
      uplifted: {title:'Playful nudge', copy:'A light, joyful blend to refresh mood—good for creative bursts or social moments.', cta:'Build a playful blend', href:'blends.html'}
    };
    const select = document.getElementById('mood-select');
    const titleEl = document.getElementById('method-title');
    const copyEl = document.getElementById('method-copy');
    const ctaEl = document.getElementById('method-cta');
    select.addEventListener('change', e=>{
      const v = e.target.value; const m = moodMap[v];
      titleEl.textContent = m.title; copyEl.textContent = m.copy; ctaEl.textContent = m.cta; ctaEl.href = m.href;
      // simple gentle pulse when changed
      ctaEl.animate([{transform:'scale(1)'},{transform:'scale(1.03)'},{transform:'scale(1)'}],{duration:420});
    });

    // Aroma wheel tooltip
    const tooltip = document.getElementById('tooltip');
    document.querySelectorAll('.note-dot').forEach(n=>{
      n.addEventListener('mouseenter', ev=>{
        tooltip.textContent = ev.target.getAttribute('data-note') + ': ' + ev.target.getAttribute('data-desc');
        tooltip.style.opacity = '1';
      });
      n.addEventListener('mousemove', ev=>{
        tooltip.style.left = ev.pageX + 'px'; tooltip.style.top = ev.pageY + 'px';
      });
      n.addEventListener('mouseleave', ()=>{tooltip.style.opacity='0';});
    });
  </script>
</body>
</html>"} 
{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg1:#fffdfa;--glass:#ffffffcc;--muted:#6a6a6a;--accent:#7b5cff}
    *{box-sizing:border-box;font-family:Georgia,serif}
    body{margin:0;background:linear-gradient(180deg,var(--bg1),#fff);color:#222}
    .nav{display:flex;justify-content:space-between;align-items:center;padding:16px 24px;background:rgba(255,255,255,0.6);backdrop-filter:blur(6px)}
    .brand{font-weight:700;color:var(--accent)}
    .menu a{margin-left:14px;text-decoration:none;color:#333}
    .hero{padding:40px 24px}
    .story{max-width:900px;margin:0 auto;background:linear-gradient(180deg,rgba(255,255,255,0.85),rgba(255,255,255,0.95));padding:22px;border-radius:14px;box-shadow:0 10px 30px rgba(20,15,40,0.03)}
    h1{margin:0 0 6px;font-family:Georgia,serif}
    p.lead{margin:0;color:var(--muted);font-size:16px}

    .sections{display:grid;grid-template-columns:1fr 320px;gap:18px;margin-top:18px;padding:0 24px}
    .panel{background:rgba(255,255,255,0.9);padding:18px;border-radius:12px}
    .process{display:flex;flex-direction:column;gap:12px}
    .step{padding:10px;border-radius:10px;background:linear-gradient(180deg,#fff,#faf8ff);border:1px solid rgba(0,0,0,0.03)}

    .wheel-wrap{display:flex;justify-content:center}
    svg.wheel{width:260px;height:260px}
    .note-info{font-size:14px;color:var(--muted);margin-top:12px}

    .cta{display:inline-block;margin-top:12px;padding:10px 14px;background:var(--accent);color:#fff;border-radius:8px;text-decoration:none}
  </style>
</head>
<body>
  <nav class="nav">
    <div class="brand">{{BUSINESS_NAME}}</div>
    <div class="menu">
      <a href="index.html">Gather</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Blends</a>
      <a href="shop.html">Boutique</a>
      <a href="pricing.html">Investment</a>
      <a href="about.html">About</a>
      <a href="book.html">Sessions</a>
      <a href="contact.html">Reach</a>
    </div>
  </nav>

  <header class="hero">
    <div class="story">
      <h1>We tell little scent stories</h1>
      <p class="lead">At {{BUSINESS_NAME}}, the work is simple: translate how you want to move through a moment into a small, repeatable scent practice you can keep. Each approach is safety-minded and tailored to your daily shape.</p>
      <div style="margin-top:12px;color:var(--muted)">Contact: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
    </div>
  </header>

  <main class="sections">
    <section>
      <div class="panel">
        <h3>Our idea of care</h3>
        <p style="color:var(--muted)">We see scent as a small companion for intention rather than a cure. Sessions teach safe use, patch testing, and how to keep formulas simple so they actually live in your routines.</p>

        <div style="margin-top:16px" class="process">
          <div class="step"><strong>Listen</strong> — a short conversation about rhythms and scent history.</div>
          <div class="step"><strong>Map</strong> — a lightweight plan: when to spritz, roll, or diffuse.</div>
          <div class="step"><strong>Create</strong> — either a ready blend or a recipe you can repeat at home.</div>
          <div class="step"><strong>Leave with notes</strong> — safety, dilution, pet considerations, and upkeep guidance.</div>
        </div>
      </div>

      <div style="margin-top:18px" class="panel">
        <h3>Social proof</h3>
        <blockquote style="margin:0;color:var(--muted)">"Simple, clear, and I still use what we made months later." — A client, {{CITY}}</blockquote>
      </div>

      <div style="margin-top:18px" class="panel">
        <h3>FAQ</h3>
        <details style="margin-top:8px"><summary>Are these medical treatments?</summary><div style="color:var(--muted);margin-top:6px">No. Aromatherapy may support everyday comfort and mood for some people. It is not medical advice.</div></details>
        <details style="margin-top:8px"><summary>How do you ensure safety?</summary><div style="color:var(--muted);margin-top:6px">Dilution guidelines and a patch test are always provided. If you have specific health concerns, consult a knowledgeable provider.</div></details>
        <details style="margin-top:8px"><summary>Pets and oils?</summary><div style="color:var(--muted);margin-top:6px">Some essential oils can be harmful to pets. Keep oils away from drinking water and ask about pet-safe alternatives during sessions.</div></details>
      </div>
    </section>

    <aside>
      <div class="panel">
        <h4>Meet the method</h4>
        <div class="wheel-wrap" aria-hidden="false">
          <svg class="wheel" viewBox="0 0 240 240" role="img" aria-label="Aroma wheel with top, middle, and base notes">
            <defs>
              <linearGradient id="rad" x1="0" x2="1"><stop offset="0" stop-color="#ffb6b9"/><stop offset="1" stop-color="#7b5cff"/></linearGradient>
            </defs>
            <circle cx="120" cy="120" r="110" fill="url(#rad)" opacity="0.08"/>
            <!-- three concentric rings as interactive notes -->
            <g id="aromawheel">
              <circle class="slice" data-type="Top" cx="120" cy="40" r="18" fill="#ffd27f" stroke="#fff" stroke-width="2"/>
              <circle class="slice" data-type="Middle" cx="200" cy="120" r="18" fill="#a7e3a0" stroke="#fff" stroke-width="2"/>
              <circle class="slice" data-type="Base" cx="40" cy="120" r="18" fill="#cdb8ff" stroke="#fff" stroke-width="2"/>
            </g>
          </svg>
        </div>
        <div id="note-desc" class="note-info">Hover over each dot to learn how the note behaves — quick to fade, the heart, or long-lasting anchors.</div>
        <a class="cta" href="book.html" style="display:block;text-align:center;margin-top:12px">Start a session</a>
      </div>

      <div style="margin-top:18px" class="panel">
        <h4>Connect</h4>
        <p style="color:var(--muted)">Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
      </div>
    </aside>
  </main>

  <script>
    // Aroma wheel hover descriptions
    const notes = document.querySelectorAll('circle.slice');
    const desc = document.getElementById('note-desc');
    const info = {
      Top: 'Top notes: bright, quick-to-evaporate scents best for an initial lift. Think citrus or light herbs.',
      Middle: 'Middle notes: the body of a blend — florals, spices, and green notes that shape the mood.',
      Base: 'Base notes: rich anchors that last longer like woods, resins, and vanillas; they give staying power.'
    };
    notes.forEach(n=>{
      n.addEventListener('mouseenter', ()=>{desc.textContent = info[n.getAttribute('data-type')]; n.style.transform='scale(1.08)'; n.style.transition='transform 0.12s';});
      n.addEventListener('mouseleave', ()=>{desc.textContent = 'Hover over each dot to learn how the note behaves — quick to fade, the heart, or long-lasting anchors.'; n.style.transform='scale(1)';});
      n.addEventListener('click', ()=>{const t=n.getAttribute('data-type'); alert(t + ' notes are highlighted — they help you choose blends.');});
    });
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Book a Session — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f6f5ff;--card:#ffffffcc;--accent:#7b5cff;--muted:#606060}
    *{box-sizing:border-box;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial}
    body{margin:0;background:linear-gradient(180deg,var(--bg),#fff);color:#222}
    .nav{display:flex;justify-content:space-between;align-items:center;padding:14px 22px;background:rgba(255,255,255,0.5);backdrop-filter:blur(6px)}
    .menu a{margin-left:12px;color:#333;text-decoration:none}
    .container{max-width:980px;margin:26px auto;padding:18px}
    .grid{display:grid;grid-template-columns:1fr 380px;gap:18px}
    .panel{background:var(--card);padding:18px;border-radius:12px;backdrop-filter:blur(6px);box-shadow:0 8px 30px rgba(16,12,40,0.04)}
    h1{margin:0 0 8px}
    .form-row{display:flex;gap:8px}
    input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(0,0,0,0.06)}
    button{padding:10px 12px;border-radius:10px;border:0;background:linear-gradient(90deg,var(--accent),#ff8da1);color:white}
    .small{font-size:13px;color:var(--muted)}
    .method-box{padding:10px;border-radius:10px;background:linear-gradient(180deg,#fff,#fafaff);border:1px solid rgba(0,0,0,0.04);margin-top:10px}

    /* interactive aroma wheel larger */
    .wheel-large{display:flex;justify-content:center;margin-top:12px}
    svg#wheel{width:320px;height:320px}
    .note-tag{display:inline-block;padding:6px 8px;border-radius:999px;background:#ffffffcc;border:1px solid rgba(0,0,0,0.04);margin:6px;font-size:13px}
  </style>
</head>
<body>
  <nav class="nav">
    <div style="font-weight:700">{{BUSINESS_NAME}}</div>
    <div class="menu">
      <a href="index.html">Gather</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Blends</a>
      <a href="shop.html">Boutique</a>
      <a href="pricing.html">Investment</a>
      <a href="about.html">About</a>
      <a href="book.html">Sessions</a>
      <a href="contact.html">Reach</a>
    </div>
  </nav>

  <main class="container">
    <div class="grid">
      <section class="panel">
        <h1>Reserve a session</h1>
        <p class="small">Choose a format and share a little about your intentions. Sessions include a safety briefing; all blends come with dilution notes and patch-test instructions.</p>

        <form id="booking-form" style="margin-top:12px">
          <label class="small">Session type</label>
          <select id="session-type" required>
            <option value="intro">Intro — 30 minutes (light plan)</option>
            <option value="deep">Guided session — 50 minutes (custom blend)</option>
            <option value="follow">Follow-up — 25 minutes (adjustments)</option>
          </select>

          <div style="margin-top:10px" class="form-row">
            <input id="name" placeholder="Your name" required />
            <input id="phone" placeholder="Phone" />
          </div>

          <div style="margin-top:10px" class="form-row">
            <input id="email" placeholder="Email" required />
            <input id="city" placeholder="City" />
          </div>

          <div style="margin-top:10px">
            <label class="small">What's your current mood?</label>
            <div style="display:flex;gap:8px;margin-top:8px">
              <button type="button" class="mood-btn" data-mood="stressed">Frazzled</button>
              <button type="button" class="mood-btn" data-mood="sleepy">Tired</button>
              <button type="button" class="mood-btn" data-mood="focus">Distracted</button>
              <button type="button" class="mood-btn" data-mood="grounded">Neutral</button>
            </div>
          </div>

          <div class="method-box" id="selected-method">
            <strong>Recommended approach</strong>
            <div id="method-desc" class="small" style="margin-top:6px">Select a mood above to see a suggested approach. The suggestion will also update the primary booking button below.</div>
          </div>

          <div style="margin-top:12px;display:flex;gap:10px;align-items:center">
            <button id="primary-book" type="submit">Book now</button>
            <div class="small" style="color:var(--muted)">Or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
          </div>
        </form>
      </section>

      <aside class="panel">
        <h3>Explore the aroma wheel</h3>
        <p class="small">Hover or tap each note to reveal descriptors. Use them as a language to describe what you want from a session.</p>

