    // Mood-to-Method for booking page
    const moodButtons = document.querySelectorAll('.mood-btn');
    const methodDesc = document.getElementById('method-desc');
    const primaryBook = document.getElementById('primary-book');

    const moodGuide = {
      stressed: {title:'Short centering', desc:'15–20 second inhalation practice, a grounding blend with a resinous base and mellow middle notes.', cta:'Book a centering session'},
      sleepy: {title:'Wind-down', desc:'A gentle bedtime recipe focusing on soft middle notes and a light base; avoid stimulating top notes.', cta:'Book a sleep consult'},
      focus: {title:'Focus cue', desc:'A targeted inhaler with bright middle notes to cue attention without overstimulation.', cta:'Book a focus consult'},
      grounded: {title:'Steady anchor', desc:'A repeated anchor sequence: slow breaths and a consistent base note for steadiness.', cta:'Book a grounding session'}
    };

    moodButtons.forEach(btn=>{
      btn.addEventListener('click', ()=>{
        moodButtons.forEach(b=>b.style.opacity='');
        btn.style.opacity='0.8';
        const m = moodGuide[btn.getAttribute('data-mood')];
        methodDesc.innerHTML = '<strong>'+m.title+'</strong><div style="margin-top:6px;color:var(--muted)">'+m.desc+'</div>';
        primaryBook.textContent = m.cta;
      });
    });

    // Aroma wheel interactivity
    const petals = document.querySelectorAll('.pet');
    const noteType = document.getElementById('note-type');
    const noteDesc = document.getElementById('note-desc');
    const details = {
      Top: 'Top notes are immediate and bright — citrus, light herbs. They change quickly and cue initial perception.',
      Middle: 'Middle notes form the character: florals, spices, and greens. They carry the theme of a blend.',
      Base: 'Base notes are long-lasting anchors like woods and resins, providing depth and slow release.'
    };
    petals.forEach(p=>{
      p.addEventListener('mouseenter', ()=>{
        const t = p.getAttribute('data-type');
        noteType.textContent = 'Type: ' + t;
        noteDesc.textContent = details[t];
        p.style.filter='url(#glow)';
      });
      p.addEventListener('mouseleave', ()=>{
        noteType.textContent = 'Type: —';
        noteDesc.textContent = 'Hover a section to read a brief description.';
        p.style.filter='none';
